import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Mining","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/mining.md","filePath":"en/guide/professions/mining.md"}'),s={name:"en/guide/professions/mining.md"};function r(o,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="mining" tabindex="-1">Mining <a class="header-anchor" href="#mining" aria-label="Permalink to &quot;Mining&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/en/game-design/professions/mining.html">full design specification</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Mining combines geological knowledge, prospecting and extraction.</li><li>Selected deposits may open authored passages; this is not unrestricted digging.</li><li>Material provenance and structural risks matter; collapse and permissions remain unresolved.</li></ul><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Mining combines prospecting, geological knowledge and extraction. Reading rock, veins and terrain should help you judge what is present and how promising it is. Regional composition and provenance can give materials distinct character.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Repeated extraction could deplete selected rock formations and open traversable spaces. This follows the existing authored-world direction, not unrestricted digging anywhere. Advanced stability awareness could help with dangerous excavations; collapse, recovery and permissions remain unresolved.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>A Geological Journal records rocks, ores, vein characteristics, regions and observations. Prospecting, efficient extraction and structural understanding offer different ways to become valuable. Better decisions should improve yield or quality, not just the number of clicks.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progression and related crafts <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Permalink to &quot;Progression and related crafts&quot;">​</a></h2><p>Use <a href="/Syrolands-Public/en/guide/professions/overview.html">shared profession learning</a>, with useful early work and deeper knowledge over time. Mining tells you what a deposit contains; <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> tells you what the material is useful for. <a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a> supports and <a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a> mechanisms are proposed advanced partners.</p><p><a href="/Syrolands-Public/en/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/en/game-design/professions/mining.html">Full design specification</a></p>',13)])])}const u=i(s,[["render",r]]);export{p as __pageData,u as default};
